INSERT INTO fc_evolution_unlock_supplement VALUES('FC27',2606,'Unlocked via the Token Store for 125 tokens','fut.gg /token-store/ (2026-10-23 열람) 「S2 Champs EVO Token」 Champions Token 125 · 2026-10-22T07:00Z~12-03 · 구매 한도 1 — 진화 생성 시각(2026-10-22T07:00:28Z)과 일치 · futmind 진화 랩 목록에 없음(해금형 정황) · 사용자 지적(챔스 토큰)','C — 정황 2개(판매 시작 시각 일치 · 진화 랩 목록 부재) + 사용자 관찰. fut.gg 상품의 evolutionId가 null이라 1차 연결 확인 없음',0,'2026-10-23');
